/**
 * Optional specific instructions for the review focus.
 */
export type ReviewRequestInstructions = string | null;

/**
 * Which party the user is reviewing this document as (e.g. 'the Buyer', a company name). Advice is oriented to that party without narrowing the analysis. Send '__neutral__' for an explicitly balanced, no-side review; omit when unknown (the review then avoids assuming a side).
 */
export type ReviewRequestPerspective = string | null;

/**
 * Optional context for review. Common keys: 'jurisdiction' (str), 'document_type' (str), 'playbook_id' (str), 'check_clauses' (bool: force the review to check the document against the org's saved clause library), 'risk_tolerance' (str: 'low'|'medium'|'high'). All keys are optional.
 */
export type ReviewRequestContext = { [key: string]: unknown };

/**
 * A completed review of a prior version of this document (#1541 P3) — this review becomes its next round: the prior findings are shown to the model and the result carries a `round` block classifying each prior finding as resolved/persisting plus the new findings. Must name the caller's own completed single-document review; both rounds must be single-document. Candidates come from GET /review/round-candidates.
 */
export type ReviewRequestPriorJobId = string | null;

/**
 * Request to review legal text for issues and suggestions.
 */
export interface ReviewRequest {
  /** The legal text to review. */
  text?: string;
  /** Optional model override. Empty uses the tiered default. */
  model?: string;
  /**
   * File IDs from /files/presign to review. Must provide text, file_ids, or document_ids.
   * @maxItems 30
   */
  fileIds?: string[];
  /**
   * Generated document IDs (past Drafter/Review output) to review.
   * @maxItems 30
   */
  documentIds?: string[];
  /** Optional specific instructions for the review focus. */
  instructions?: ReviewRequestInstructions;
  /** Which party the user is reviewing this document as (e.g. 'the Buyer', a company name). Advice is oriented to that party without narrowing the analysis. Send '__neutral__' for an explicitly balanced, no-side review; omit when unknown (the review then avoids assuming a side). */
  perspective?: ReviewRequestPerspective;
  /** Optional context for review. Common keys: 'jurisdiction' (str), 'document_type' (str), 'playbook_id' (str), 'check_clauses' (bool: force the review to check the document against the org's saved clause library), 'risk_tolerance' (str: 'low'|'medium'|'high'). All keys are optional. */
  context?: ReviewRequestContext;
  /** A completed review of a prior version of this document (#1541 P3) — this review becomes its next round: the prior findings are shown to the model and the result carries a `round` block classifying each prior finding as resolved/persisting plus the new findings. Must name the caller's own completed single-document review; both rounds must be single-document. Candidates come from GET /review/round-candidates. */
  priorJobId?: ReviewRequestPriorJobId;
}

