export type ReviewRoundPriorStatusStatus = typeof ReviewRoundPriorStatusStatus[keyof typeof ReviewRoundPriorStatusStatus];


// eslint-disable-next-line @typescript-eslint/no-redeclare
export const ReviewRoundPriorStatusStatus = {
  resolved: 'resolved',
  persisting: 'persisting',
  unknown: 'unknown',
} as const;

/**
 * One prior-round finding's fate in the current round (#1541 P3).

`finding_key` indexes the PRIOR review's raw stored arrays (issue:{i} /
deviation:{i}, same contract as services/review_findings.py); `label` and
`severity` are snapshots so the FE renders resolved findings without
fetching the prior result. `status` is model-assigned inference —
`unknown` is the honest degraded value when classification was
unavailable, never a guess. `matched_finding_key` names the CURRENT
round's finding a persisting concern maps to ("" when none does).
 */
export interface ReviewRoundPriorStatus {
  findingKey: string;
  label?: string;
  severity?: string;
  status?: ReviewRoundPriorStatusStatus;
  matchedFindingKey?: string;
  note?: string;
}

/**
 * Round metadata + finding deltas on a round-2+ review (#1541 P3).

`number` is this review's round (2 for the first follow-up). `new_finding_keys`
is derived mechanically — current findings no prior finding matched — so
resolved/persisting/new partitions both rounds' findings between
`prior_statuses` and this list.
 */
export interface ReviewRoundResult {
  priorJobId: string;
  number?: number;
  priorStatuses?: ReviewRoundPriorStatus[];
  newFindingKeys?: string[];
}

